  citySlug: string;       // e.g. "new-york"
  cityName: string;       // e.g. "New York"
  areaSlug: string;       // e.g. "williamsburg"
  areaName: string;       // e.g. "Williamsburg"
  borough?: string;       // e.g. "Brooklyn"
  tier: 1 | 2 | 3 | 4 | 5 | 6;
